<script setup>
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { Activity, AlertTriangle, Ban, BarChart3, Check, CheckCircle2, ChevronDown, ChevronLeft, ChevronRight, Clock3, Download, Eye, FilePlus2, Gauge, History, LockKeyhole, MoreHorizontal, Plus, RefreshCw, Search, Settings2, ShieldAlert, ShieldCheck, SlidersHorizontal, TrendingUp, X } from '@lucide/vue'
import { createRiskBlacklistEntry, deleteRiskBlacklistEntry, getRiskPolicy, getSecurityOverview, listAuditLogs, listRiskBlacklist, saveRiskPolicy, updateSecurityEventStatus } from '../../api/admin'

const levels = { low: '低风险', medium: '中风险', high: '高风险' }
const types = { login: '异常登录', api: 'API高频访问', ai: 'AI接口异常', access: '非法访问', block: '系统自动拦截', blacklist: '黑名单触发' }
const statuses = { pending: '待处理', processed: '已处理', ignored: '忽略', blocked: '自动拦截' }
const typeLabels = { user: '用户', ip: 'IP地址', keyword: '关键词', 'api-key': 'API Key' }
const defaultConfig = { loginDetection: true, apiRateDetection: true, promptDetection: true, bruteForceDetection: true, ipDetection: true, autoBlock: true, ipRequestsPerMinute: 120, aiRequestsPerMinute: 30, loginFailureThreshold: 5, autoBlockDuration: '24h', eventRetentionDays: 90 }
const pageSizes = [4, 10, 20, 50]
const emptyRule = () => ({ id: '', name: '', type: 'API', level: 'medium', configLabel: '120次 / 分钟', configValue: '120', configUnit: '次 / 分钟', action: '限流', description: '', enabled: true })

const overview = ref({ metrics: [], events: [], serviceStatus: '检查中', generatedAt: null })
const rules = ref([]); const config = ref({ ...defaultConfig }); const blacklist = ref([]); const events = ref([])
const audits = ref([]); const auditLoading = ref(false); const isRefreshing = ref(false); const isSaving = ref(false); const errorMessage = ref(''); const toast = ref(''); let toastTimer = 0
const trendRange = ref('24h'); const selectedRisk = ref('all'); const activeFilter = ref(''); const showOnlyPending = ref(false)
const settingsDraft = ref(null); const ruleDraft = ref(null); const blacklistDraft = ref(null); const selectedBlacklist = ref(null); const selectedEvent = ref(null); const confirmAction = ref(null); const showSettings = ref(false); const showRuleEditor = ref(false); const showAudit = ref(false)
const blacklistQuery = ref(''); const blacklistType = ref('all'); const blacklistStatus = ref('all'); const blacklistSource = ref('all'); const blacklistPage = ref(1); const blacklistSize = ref(4)
const eventQuery = ref(''); const eventRisk = ref('all'); const eventType = ref('all'); const eventStatus = ref('all'); const eventTime = ref('all'); const eventPage = ref(1); const eventSize = ref(4)

const metricMap = computed(() => Object.fromEntries((overview.value.metrics || []).map((item) => [item.label, item])))
const enabledRules = computed(() => rules.value.filter((rule) => rule.enabled).length)
const abnormalLogins = computed(() => events.value.filter((event) => event.type === 'login').length)
const metrics = computed(() => [metricMap.value['今日请求'] || { label: '今日请求', value: '--', hint: '过去24小时', tone: 'neutral' }, metricMap.value['风险请求'] || { label: '风险请求', value: '--', hint: '过去24小时', tone: 'warning' }, metricMap.value['已拦截'] || { label: '已拦截', value: '--', hint: '自动阻止', tone: 'success' }, { label: '异常登录', value: events.value.length ? abnormalLogins.value : '--', hint: '过去24小时', tone: 'danger' }, metricMap.value['黑名单'] || { label: '黑名单', value: '--', hint: '当前生效对象', tone: 'danger' }, metricMap.value['待处理事件'] || { label: '待处理事件', value: '--', hint: '需要管理员复核', tone: 'warning' }])
const strategies = computed(() => { const map = Object.fromEntries(rules.value.map((rule) => [rule.id, rule])); return [{ id: 'login-failure', title: '登录保护', icon: LockKeyhole, fallback: '连续失败 5 次，临时锁定 30 分钟' }, { id: 'ip-rate-limit', title: 'API 限流', icon: Gauge, fallback: '单 IP 120 次 / 分钟' }, { id: 'ai-frequency', title: 'AI 调用保护', icon: Activity, fallback: '单用户 30 次 / 分钟' }, { id: 'sensitive-content', title: 'Prompt 风险检测', icon: ShieldAlert, fallback: '恶意指令、注入、超长输入' }, { id: 'unusual-login', title: 'IP 风险控制', icon: ShieldCheck, fallback: '异常 IP 自动临时封禁' }].map((item) => ({ ...item, rule: map[item.id] })) })
const distribution = computed(() => ['high', 'medium', 'low'].map((value) => ({ value, label: levels[value], count: events.value.filter((event) => event.level === value).length })))
const filteredBlacklist = computed(() => { const keyword = blacklistQuery.value.trim().toLowerCase(); return blacklist.value.filter((item) => (!keyword || [item.object, item.reason, item.id].some((value) => String(value || '').toLowerCase().includes(keyword))) && (blacklistType.value === 'all' || item.type === blacklistType.value) && (blacklistStatus.value === 'all' || item.status === blacklistStatus.value) && (blacklistSource.value === 'all' || item.source === blacklistSource.value)) })
const blacklistPages = computed(() => Math.max(1, Math.ceil(filteredBlacklist.value.length / blacklistSize.value))); const blacklistRows = computed(() => filteredBlacklist.value.slice((blacklistPage.value - 1) * blacklistSize.value, blacklistPage.value * blacklistSize.value))
const filteredEvents = computed(() => { const keyword = eventQuery.value.trim().toLowerCase(); const now = Date.now(); return events.value.filter((event) => { const age = now - new Date(event.timestampRaw || event.timestamp).getTime(); return (!keyword || [event.userId, event.maskedIp, event.traceId, event.subject, event.summary].some((value) => String(value || '').toLowerCase().includes(keyword))) && (eventRisk.value === 'all' || event.level === eventRisk.value) && (eventType.value === 'all' || event.type === eventType.value) && (eventStatus.value === 'all' || event.status === eventStatus.value) && (eventTime.value === 'all' || (eventTime.value === '24h' && age <= 86400000) || (eventTime.value === '7d' && age <= 604800000)) && (!showOnlyPending.value || event.status === 'pending') && (selectedRisk.value === 'all' || event.level === selectedRisk.value) }) })
const eventPages = computed(() => Math.max(1, Math.ceil(filteredEvents.value.length / eventSize.value))); const eventRows = computed(() => filteredEvents.value.slice((eventPage.value - 1) * eventSize.value, eventPage.value * eventSize.value))
const trend = computed(() => { const count = trendRange.value === '24h' ? 12 : trendRange.value === '7d' ? 7 : 10; const now = new Date(); return Array.from({ length: count }, (_, index) => { const start = new Date(now); if (trendRange.value === '24h') start.setHours(now.getHours() - (count - index - 1) * 2, 0, 0, 0); else start.setDate(now.getDate() - (count - index - 1)); const end = new Date(start); trendRange.value === '24h' ? end.setHours(end.getHours() + 2) : end.setDate(end.getDate() + 1); const matches = events.value.filter((event) => { const date = new Date(event.timestampRaw || event.timestamp); return date >= start && date < end }); return { label: trendRange.value === '24h' ? `${String(start.getHours()).padStart(2, '0')}:00` : `${start.getMonth() + 1}/${start.getDate()}`, normal: Math.max(0, Math.round((Number(metricMap.value['今日请求']?.value) || 0) / count - matches.length)), risk: matches.length, blocked: matches.filter((event) => event.status === 'blocked' || event.type === 'block').length } }) })
const trendMax = computed(() => Math.max(1, ...trend.value.flatMap((point) => [point.normal, point.risk, point.blocked]))); const trendLine = (key) => trend.value.map((point, index) => `${Math.round(index / Math.max(1, trend.value.length - 1) * 100)},${100 - Math.round(point[key] / trendMax.value * 86)}`).join(' ')

function formatNumber(value) { return typeof value === 'number' ? value.toLocaleString('zh-CN') : value ?? '--' }
function formatDate(value) { if (!value) return '—'; const date = new Date(value); return Number.isNaN(date.getTime()) ? String(value) : date.toLocaleString('zh-CN', { hour12: false }).replace(/\//g, '-') }
function toastMessage(message) { toast.value = message; clearTimeout(toastTimer); toastTimer = window.setTimeout(() => { toast.value = '' }, 2800) }
function normalizeRule(rule) { const item = { ...emptyRule(), ...rule }; item.configLabel = item.configLabel || (item.configValue ? `${item.configValue} ${item.configUnit || ''}` : '已启用'); return item }
function normalizeEvent(event) { return { ...event, timestampRaw: event.timestamp, timestamp: formatDate(event.timestamp), userId: event.userId || '—', maskedIp: event.maskedIp || '—', traceId: event.traceId || '—', subject: event.subject || `${event.userId || '—'} / ${event.maskedIp || '—'}`, status: event.status || 'pending' } }
function normalizeBlacklist(item) { return { ...item, id: item.key ?? item.id, type: item.type === 'user_id' ? 'user' : item.type, object: item.object ?? item.value ?? '', status: item.status || 'active', source: item.source || (item.createdBy ? '管理员添加' : '系统自动'), createdAt: formatDate(item.createdAt || item.updatedAt), duration: ({ '1h': '1小时', '24h': '24小时', '7d': '7天', '30d': '30天', permanent: '永久' })[item.duration] || item.duration || '永久' } }
async function loadData() { errorMessage.value = ''; try { const [security, policy, entries] = await Promise.all([getSecurityOverview(), getRiskPolicy(), listRiskBlacklist()]); overview.value = security || { metrics: [], events: [], serviceStatus: '未知' }; events.value = Array.isArray(security?.events) ? security.events.map(normalizeEvent) : []; rules.value = Array.isArray(policy?.rules) ? policy.rules.map(normalizeRule) : []; config.value = { ...defaultConfig, ...(policy?.config || {}) }; blacklist.value = Array.isArray(entries) ? entries.map(normalizeBlacklist) : [] } catch (error) { errorMessage.value = error?.message || '安全数据加载失败'; overview.value = { metrics: [], events: [], serviceStatus: '读取失败' } } }
async function refresh() { isRefreshing.value = true; try { await loadData(); toastMessage('安全数据已更新') } finally { isRefreshing.value = false } }
async function savePolicy() { await saveRiskPolicy({ rules: rules.value, config: config.value }) }
function openSettings() { settingsDraft.value = { ...config.value }; showSettings.value = true }
async function saveSettings() { isSaving.value = true; try { await saveRiskPolicy({ rules: rules.value, config: settingsDraft.value }); config.value = { ...settingsDraft.value }; showSettings.value = false; toastMessage('风控设置已保存') } catch { toastMessage('风控设置保存失败') } finally { isSaving.value = false } }
function openRule(rule = null) { ruleDraft.value = normalizeRule(rule || emptyRule()); showRuleEditor.value = true }
async function saveRule() { if (!ruleDraft.value.name.trim()) return toastMessage('请填写规则名称'); const item = normalizeRule({ ...ruleDraft.value, id: ruleDraft.value.id || `custom-${Date.now()}` }); const index = rules.value.findIndex((rule) => rule.id === item.id); if (index >= 0) rules.value[index] = item; else rules.value.push(item); isSaving.value = true; try { await savePolicy(); showRuleEditor.value = false; toastMessage(index >= 0 ? '规则已更新' : '规则已创建') } catch { toastMessage('规则保存失败') } finally { isSaving.value = false } }
async function toggleRule(rule) { const previous = rule.enabled; rule.enabled = !rule.enabled; try { await savePolicy(); toastMessage(rule.enabled ? '规则已启用' : '规则已停用') } catch { rule.enabled = previous; toastMessage('规则状态保存失败') } }
function openBlacklist(prefill = null) { blacklistDraft.value = prefill ? { type: prefill.userId !== '—' ? 'user' : 'ip', object: prefill.userId !== '—' ? prefill.userId : prefill.maskedIp, reason: `由安全事件 ${prefill.id} 触发`, duration: '24h', source: '系统自动' } : { type: 'user', object: '', reason: '', duration: '24h', source: '管理员添加' } }
async function createBlacklist() { if (!blacklistDraft.value?.object.trim() || !blacklistDraft.value.reason.trim()) return toastMessage('请填写对象和风险原因'); isSaving.value = true; try { await createRiskBlacklistEntry(blacklistDraft.value); await loadData(); blacklistDraft.value = null; toastMessage('黑名单已添加') } catch { toastMessage('黑名单保存失败') } finally { isSaving.value = false } }
async function updateEvent(event, status) { isSaving.value = true; try { await updateSecurityEventStatus(event.id, status); await loadData(); selectedEvent.value = events.value.find((item) => item.id === event.id) || null; toastMessage(status === 'processed' ? '事件已标记为已处理' : '事件已忽略') } catch { toastMessage('事件状态保存失败') } finally { isSaving.value = false } }
function confirmBlacklist(item) { confirmAction.value = { type: 'remove', item } }
function confirmBlock(event) { confirmAction.value = { type: 'block', event } }
async function executeConfirm() { const action = confirmAction.value; confirmAction.value = null; if (!action) return; isSaving.value = true; try { if (action.type === 'remove') { await deleteRiskBlacklistEntry(action.item.id); await loadData(); selectedBlacklist.value = null; toastMessage('黑名单已解除') } else { await createRiskBlacklistEntry({ type: action.event.userId !== '—' ? 'user' : 'ip', object: action.event.userId !== '—' ? action.event.userId : action.event.maskedIp, reason: `事件 ${action.event.id} 风险处置`, duration: '24h', source: '系统自动' }); await updateSecurityEventStatus(action.event.id, 'blocked'); await loadData(); selectedEvent.value = null; toastMessage('风险对象已临时封禁24小时') } } catch { toastMessage('安全处置失败') } finally { isSaving.value = false } }
function filterOptions(name) { return ({ blacklistType: [{ value: 'all', label: '全部类型' }, { value: 'user', label: '用户' }, { value: 'ip', label: 'IP地址' }, { value: 'api-key', label: 'API Key' }], blacklistStatus: [{ value: 'all', label: '全部状态' }, { value: 'active', label: '生效中' }, { value: 'expired', label: '已过期' }], blacklistSource: [{ value: 'all', label: '全部来源' }, { value: '系统自动', label: '系统自动' }, { value: '管理员添加', label: '管理员添加' }], eventRisk: [{ value: 'all', label: '全部风险等级' }, { value: 'high', label: '高风险' }, { value: 'medium', label: '中风险' }, { value: 'low', label: '低风险' }], eventType: [{ value: 'all', label: '全部事件类型' }, ...Object.entries(types).map(([value, label]) => ({ value, label }))], eventStatus: [{ value: 'all', label: '全部处理状态' }, { value: 'pending', label: '待处理' }, { value: 'processed', label: '已处理' }, { value: 'blocked', label: '自动拦截' }, { value: 'ignored', label: '忽略' }], eventTime: [{ value: 'all', label: '全部时间' }, { value: '24h', label: '过去24小时' }, { value: '7d', label: '过去7天' }]}[name]) }
function filterRef(name) { return ({ blacklistType, blacklistStatus, blacklistSource, eventRisk, eventType, eventStatus, eventTime })[name] }
function filterLabel(name) { return filterOptions(name).find((item) => item.value === filterRef(name).value)?.label || filterOptions(name)[0].label }
function setFilter(name, value) { filterRef(name).value = value; activeFilter.value = '' }
function toggleFilter(name) { activeFilter.value = activeFilter.value === name ? '' : name }
function changePage(kind, page) { if (kind === 'blacklist') blacklistPage.value = Math.max(1, Math.min(blacklistPages.value, page)); else eventPage.value = Math.max(1, Math.min(eventPages.value, page)) }
function selectRisk(value) { selectedRisk.value = selectedRisk.value === value ? 'all' : value }
function exportEvents() { const rows = [['时间', '风险等级', '事件类型', '用户/IP', '风险描述', '命中规则', '处理状态'], ...filteredEvents.value.map((event) => [event.timestamp, levels[event.level], types[event.type], event.subject, event.summary, event.rule, statuses[event.status]])]; const blob = new Blob([rows.map((row) => row.map((value) => `"${String(value || '').replaceAll('"', '""')}"`).join(',')).join('\n')], { type: 'text/csv;charset=utf-8' }); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = `security-events-${Date.now()}.csv`; link.click(); URL.revokeObjectURL(url); toastMessage('安全事件记录已导出') }
async function openAudit() { showAudit.value = true; auditLoading.value = true; try { const response = await listAuditLogs({ page: 0, size: 20 }); audits.value = response?.items || response?.data?.items || [] } catch { toastMessage('操作记录加载失败') } finally { auditLoading.value = false } }
watch([blacklistQuery, blacklistType, blacklistStatus, blacklistSource, blacklistSize], () => { blacklistPage.value = 1 }); watch([eventQuery, eventRisk, eventType, eventStatus, eventTime, eventSize, showOnlyPending, selectedRisk], () => { eventPage.value = 1 }); watch(blacklistPages, (page) => { if (blacklistPage.value > page) blacklistPage.value = page }); watch(eventPages, (page) => { if (eventPage.value > page) eventPage.value = page })
function closeActiveFilter() { activeFilter.value = '' }
onMounted(() => { void loadData(); window.addEventListener('click', closeActiveFilter) }); onBeforeUnmount(() => { clearTimeout(toastTimer); window.removeEventListener('click', closeActiveFilter) })
</script>

<template>
  <section class="admin-section-page security-page-shell">
    <header class="security-page-header"><div><p>安全运营中心</p><h2>安全与风控</h2><span>统一管理系统安全策略、访问控制、异常行为与风险事件</span></div><div class="security-page-actions"><span class="security-service-status" :class="{ 'is-alert': overview.serviceStatus !== '正常' }"><i></i>风控服务{{ overview.serviceStatus || '检查中' }}</span><button type="button" class="admin-ghost-button" :disabled="isRefreshing" @click="refresh"><RefreshCw :size="15" :class="{ 'is-spinning': isRefreshing }" />刷新数据</button><button type="button" class="admin-primary-button" @click="openSettings"><Settings2 :size="15" />风控设置</button></div></header>
    <div class="security-page-scroll">
      <div v-if="errorMessage" class="security-error-state"><div><AlertTriangle :size="17" /><strong>安全数据加载失败</strong><span>{{ errorMessage }}</span></div><button type="button" class="admin-primary-button" @click="refresh">重新加载</button></div>
      <section class="security-metric-grid"><article v-for="metric in metrics" :key="metric.label" class="security-metric-card" :class="`is-${metric.tone}`"><span>{{ metric.label }}</span><strong>{{ formatNumber(metric.value) }}</strong><small>{{ metric.hint }} · 统计范围：过去24小时</small></article></section>
      <section class="security-monitor-grid"><article class="security-panel"><header class="security-panel-header"><div><h3><TrendingUp :size="17" />最近风险趋势</h3><p>基于真实安全事件与今日请求统计</p></div><div class="security-segmented"><button v-for="item in [{ value: '24h', label: '24小时' }, { value: '7d', label: '7天' }, { value: '30d', label: '30天' }]" :key="item.value" type="button" :class="{ active: trendRange === item.value }" @click="trendRange = item.value">{{ item.label }}</button></div></header><div class="security-chart"><svg viewBox="0 0 100 100" preserveAspectRatio="none"><polyline v-for="line in ['normal', 'risk', 'blocked']" :key="line" :points="trendLine(line)" fill="none" :stroke="line === 'normal' ? '#94a3b8' : line === 'risk' ? '#f59e0b' : '#ef4444'" :stroke-width="line === 'normal' ? 1.3 : 1.8" vector-effect="non-scaling-stroke" /></svg><div><span v-for="point in trend" :key="point.label">{{ point.label }}</span></div></div><footer class="security-chart-legend"><span><i></i>正常请求</span><span><i class="risk"></i>风险请求</span><span><i class="blocked"></i>已拦截</span></footer></article><article class="security-panel"><header class="security-panel-header"><div><h3><BarChart3 :size="17" />风险等级分布</h3><p>点击等级筛选安全事件</p></div><span class="security-updated">{{ overview.generatedAt ? formatDate(overview.generatedAt) : '实时' }}</span></header><div class="security-distribution-list"><button v-for="item in distribution" :key="item.value" type="button" :class="['security-distribution-row', `is-${item.value}`, { active: selectedRisk === item.value }]" @click="selectRisk(item.value)"><span><i></i>{{ item.label }}</span><strong>{{ item.count }}</strong><ChevronRight :size="14" /></button></div><div class="security-distribution-summary"><div><span>自动拦截率</span><strong>{{ events.length ? `${Math.round(events.filter((event) => ['blocked', 'processed'].includes(event.status)).length / events.length * 1000) / 10}%` : '--' }}</strong></div><div><span>风险规则命中</span><strong>{{ events.length || '--' }}次</strong></div><div><span>当前启用规则</span><strong>{{ enabledRules }}条</strong></div></div></article></section>
      <section class="security-panel"><header class="security-panel-header"><div><h3><ShieldCheck :size="17" />风控策略</h3><p>关键安全策略状态和阈值一览，管理员只能看到脱敏风险摘要。</p></div><span class="security-privacy-note"><ShieldAlert :size="14" />用户 Prompt 与项目内容不会展示</span></header><div class="security-strategy-grid"><article v-for="card in strategies" :key="card.id" class="security-strategy-card"><div class="security-strategy-top"><span><component :is="card.icon" :size="15" /></span><div><h4>{{ card.title }}</h4><small :class="{ off: card.rule && !card.rule.enabled }">{{ card.rule?.enabled === false ? '已关闭' : '已开启' }}</small></div><button type="button" @click="card.rule ? openRule(card.rule) : openSettings()"><Settings2 :size="14" /></button></div><p>{{ card.rule?.description || card.fallback }}</p><footer><strong>{{ card.rule?.configLabel || card.fallback }}</strong><button type="button" class="security-link-button" @click="card.rule ? openRule(card.rule) : openSettings()">配置</button></footer></article></div></section>
      <section class="security-panel"><header class="security-panel-header"><div><h3><SlidersHorizontal :size="17" />风控规则</h3><p>创建、编辑和启停风险检测规则，变更会写入安全审计。</p></div><button type="button" class="admin-primary-button" @click="openRule()"><FilePlus2 :size="15" />新建规则</button></header><div class="security-table-wrap"><table class="security-table rules-table"><thead><tr><th>规则名称</th><th>类型</th><th>条件</th><th>动作</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="rule in rules.slice(0, 9)" :key="rule.id"><td><strong>{{ rule.name }}</strong><small>{{ rule.description }}</small></td><td>{{ rule.type || '安全' }}</td><td>{{ rule.configLabel || '按规则检测' }}</td><td>{{ rule.action || '记录' }}</td><td><label class="security-switch"><input type="checkbox" :checked="rule.enabled" @change="toggleRule(rule)" /><span></span><em>{{ rule.enabled ? '启用' : '停用' }}</em></label></td><td><button type="button" class="security-link-button" @click="openRule(rule)">编辑</button><button type="button" class="security-icon-button"><MoreHorizontal :size="14" /></button></td></tr><tr v-if="!rules.length"><td colspan="6" class="security-empty">暂无已配置规则</td></tr></tbody></table></div></section>
      <section class="security-panel"><header class="security-panel-header"><div><h3><Ban :size="17" />黑名单管理</h3><p>管理被平台策略暂时限制的用户、IP 地址和 API Key。</p></div><button type="button" class="admin-primary-button" @click="openBlacklist()"><Plus :size="15" />添加黑名单</button></header><div class="security-table-toolbar"><label class="security-search"><Search :size="15" /><input v-model="blacklistQuery" type="search" placeholder="搜索用户ID / IP / 关键词" /></label><div v-for="name in ['blacklistType', 'blacklistStatus', 'blacklistSource']" :key="name" class="security-filter-select" @click.stop><button type="button" class="security-filter-trigger" @click="toggleFilter(name)">{{ filterLabel(name) }}<ChevronDown :size="14" /></button><div v-if="activeFilter === name" class="security-filter-menu"><button v-for="item in filterOptions(name)" :key="item.value" type="button" :class="{ selected: filterRef(name).value === item.value }" @click="setFilter(name, item.value)">{{ item.label }}<Check v-if="filterRef(name).value === item.value" :size="13" /></button></div></div></div><div class="security-table-wrap"><table class="security-table"><thead><tr><th>类型</th><th>对象</th><th>风险原因</th><th>来源</th><th>加入时间</th><th>有效期</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in blacklistRows" :key="item.id"><td><span class="security-type-tag" :class="`is-${item.type}`">{{ typeLabels[item.type] || item.type }}</span></td><td><code>{{ item.object }}</code></td><td>{{ item.reason }}</td><td>{{ item.source }}</td><td>{{ item.createdAt }}</td><td>{{ item.duration }}</td><td><span class="security-status-tag" :class="`is-${item.status}`">{{ item.status === 'active' ? '生效中' : '已过期' }}</span></td><td><button type="button" class="security-link-button" @click="selectedBlacklist = item">查看</button><button type="button" class="security-link-button danger" :disabled="item.status === 'expired'" @click="confirmBlacklist(item)">解封</button></td></tr><tr v-if="!blacklistRows.length"><td colspan="8" class="security-empty">{{ blacklistQuery || blacklistType !== 'all' || blacklistStatus !== 'all' || blacklistSource !== 'all' ? '没有符合当前筛选条件的记录' : '暂无黑名单对象' }}</td></tr></tbody></table></div><footer class="security-pagination"><span>共 {{ filteredBlacklist.length }} 条记录</span><div><label>每页<select v-model.number="blacklistSize"><option v-for="size in pageSizes" :key="size" :value="size">{{ size }}</option></select></label><button type="button" :disabled="blacklistPage === 1" @click="changePage('blacklist', blacklistPage - 1)"><ChevronLeft :size="14" /></button><button type="button" :disabled="blacklistPage >= blacklistPages" @click="changePage('blacklist', blacklistPage + 1)"><ChevronRight :size="14" /></button></div></footer></section>
      <section class="security-panel"><header class="security-panel-header"><div><h3><AlertTriangle :size="17" />安全事件</h3><p>记录系统检测到的异常访问、接口滥用与风险行为。</p></div><div class="security-event-actions"><label class="security-check"><input v-model="showOnlyPending" type="checkbox" />仅显示未处理</label><button type="button" class="security-link-button" @click="openAudit"><History :size="14" />查看操作记录</button><button type="button" class="admin-ghost-button" @click="exportEvents"><Download :size="14" />导出记录</button></div></header><div class="security-table-toolbar"><label class="security-search"><Search :size="15" /><input v-model="eventQuery" type="search" placeholder="搜索用户ID / IP / Trace ID" /></label><div v-for="name in ['eventRisk', 'eventType', 'eventStatus', 'eventTime']" :key="name" class="security-filter-select" @click.stop><button type="button" class="security-filter-trigger" @click="toggleFilter(name)">{{ filterLabel(name) }}<ChevronDown :size="14" /></button><div v-if="activeFilter === name" class="security-filter-menu"><button v-for="item in filterOptions(name)" :key="item.value" type="button" :class="{ selected: filterRef(name).value === item.value }" @click="setFilter(name, item.value)">{{ item.label }}<Check v-if="filterRef(name).value === item.value" :size="13" /></button></div></div></div><div class="security-table-wrap"><table class="security-table event-table"><thead><tr><th>时间</th><th>风险等级</th><th>事件类型</th><th>用户 / IP</th><th>风险描述</th><th>命中规则</th><th>处理状态</th><th>操作</th></tr></thead><tbody><tr v-for="event in eventRows" :key="event.id"><td>{{ event.timestamp }}</td><td><span class="security-risk-tag" :class="`is-${event.level}`"><i></i>{{ levels[event.level] }}</span></td><td>{{ types[event.type] || event.type }}</td><td><strong>{{ event.subject }}</strong></td><td class="summary">{{ event.summary }}</td><td>{{ event.rule }}</td><td><span class="security-status-tag" :class="`is-${event.status}`">{{ statuses[event.status] || event.status }}</span></td><td><button type="button" class="security-link-button" @click="selectedEvent = event"><Eye :size="13" />查看</button></td></tr><tr v-if="!eventRows.length"><td colspan="8" class="security-empty"><CheckCircle2 :size="16" />{{ eventQuery || eventRisk !== 'all' || eventType !== 'all' || eventStatus !== 'all' || selectedRisk !== 'all' ? '没有符合当前筛选条件的记录' : '当前未检测到需要处理的安全事件' }}<small>系统正在持续进行风险检测</small></td></tr></tbody></table></div><footer class="security-pagination"><span>共 {{ filteredEvents.length }} 条记录</span><div><label>每页<select v-model.number="eventSize"><option v-for="size in pageSizes" :key="size" :value="size">{{ size }}</option></select></label><button type="button" :disabled="eventPage === 1" @click="changePage('event', eventPage - 1)"><ChevronLeft :size="14" /></button><button type="button" :disabled="eventPage >= eventPages" @click="changePage('event', eventPage + 1)"><ChevronRight :size="14" /></button></div></footer></section>
    </div>
    <Teleport to="body">
      <Transition name="security-drawer"><div v-if="showSettings" class="security-overlay" @pointerdown.self="showSettings = false"><aside class="security-drawer"><header><div><span>安全控制</span><h3>风控设置</h3></div><button type="button" @click="showSettings = false"><X :size="18" /></button></header><div class="security-drawer-body"><div class="settings-grid"><label v-for="item in [{ key: 'loginDetection', label: '异常登录检测' }, { key: 'apiRateDetection', label: 'API 高频调用检测' }, { key: 'promptDetection', label: 'Prompt 风险检测' }, { key: 'bruteForceDetection', label: '暴力请求检测' }, { key: 'ipDetection', label: 'IP 异常访问检测' }, { key: 'autoBlock', label: '自动临时封禁' }]" :key="item.key"><span>{{ item.label }}</span><input v-model="settingsDraft[item.key]" type="checkbox" /></label></div><label class="drawer-field"><span>单 IP 每分钟最大请求数</span><input v-model.number="settingsDraft.ipRequestsPerMinute" type="number" /></label><label class="drawer-field"><span>单用户每分钟最大 AI 请求数</span><input v-model.number="settingsDraft.aiRequestsPerMinute" type="number" /></label><label class="drawer-field"><span>连续登录失败阈值</span><input v-model.number="settingsDraft.loginFailureThreshold" type="number" /></label><label class="drawer-field"><span>自动封禁时长</span><select v-model="settingsDraft.autoBlockDuration"><option value="1h">1小时</option><option value="24h">24小时</option><option value="7d">7天</option></select></label><label class="drawer-field"><span>风险事件保留天数</span><input v-model.number="settingsDraft.eventRetentionDays" type="number" /></label></div><footer><button type="button" class="admin-ghost-button" @click="showSettings = false">取消</button><button type="button" class="admin-primary-button" :disabled="isSaving" @click="saveSettings">{{ isSaving ? '保存中...' : '保存设置' }}</button></footer></aside></div></Transition>
      <Transition name="security-drawer"><div v-if="showRuleEditor" class="security-overlay" @pointerdown.self="showRuleEditor = false"><aside class="security-drawer"><header><div><span>策略配置</span><h3>{{ ruleDraft?.id ? '编辑风控规则' : '新建风控规则' }}</h3></div><button type="button" @click="showRuleEditor = false"><X :size="18" /></button></header><div class="security-drawer-body"><label class="drawer-field"><span>规则名称 *</span><input v-model="ruleDraft.name" placeholder="例如：异常 IP 访问" /></label><label class="drawer-field"><span>规则类型</span><input v-model="ruleDraft.type" placeholder="API / 登录 / AI / IP" /></label><label class="drawer-field"><span>检测条件</span><input v-model="ruleDraft.configLabel" placeholder="例如：>120次 / 分钟" /></label><label class="drawer-field"><span>风险等级</span><select v-model="ruleDraft.level"><option value="low">低风险</option><option value="medium">中风险</option><option value="high">高风险</option></select></label><label class="drawer-field"><span>执行动作</span><select v-model="ruleDraft.action"><option>仅记录</option><option>警告</option><option>限流</option><option>临时封禁</option><option>永久封禁</option></select></label><label class="drawer-field"><span>规则说明</span><textarea v-model="ruleDraft.description" rows="3"></textarea></label><label class="security-check"><input v-model="ruleDraft.enabled" type="checkbox" />保存后立即启用</label></div><footer><button type="button" class="admin-ghost-button" @click="showRuleEditor = false">取消</button><button type="button" class="admin-primary-button" :disabled="isSaving" @click="saveRule">{{ isSaving ? '保存中...' : '保存规则' }}</button></footer></aside></div></Transition>
      <Transition name="security-drawer"><div v-if="blacklistDraft" class="security-overlay" @pointerdown.self="blacklistDraft = null"><aside class="security-drawer"><header><div><span>安全处置</span><h3>添加黑名单</h3></div><button type="button" @click="blacklistDraft = null"><X :size="18" /></button></header><div class="security-drawer-body"><label class="drawer-field"><span>对象类型 *</span><select v-model="blacklistDraft.type"><option value="user">用户</option><option value="ip">IP地址</option><option value="api-key">API Key</option></select></label><label class="drawer-field"><span>对象 *</span><input v-model="blacklistDraft.object" placeholder="输入用户ID、IP地址或 API Key" /></label><label class="drawer-field"><span>风险原因 *</span><textarea v-model="blacklistDraft.reason" rows="3"></textarea></label><label class="drawer-field"><span>封禁时长 *</span><select v-model="blacklistDraft.duration"><option value="1h">1小时</option><option value="24h">24小时</option><option value="7d">7天</option><option value="30d">30天</option><option value="permanent">永久</option></select></label><label class="drawer-field"><span>管理员内部备注</span><input v-model="blacklistDraft.note" /></label></div><footer><button type="button" class="admin-ghost-button" @click="blacklistDraft = null">取消</button><button type="button" class="admin-danger-button" :disabled="isSaving" @click="createBlacklist"><Ban :size="14" />{{ isSaving ? '处理中...' : '确认封禁' }}</button></footer></aside></div></Transition>
      <Transition name="security-drawer"><div v-if="selectedBlacklist" class="security-overlay" @pointerdown.self="selectedBlacklist = null"><aside class="security-drawer"><header><div><span>黑名单审计</span><h3>黑名单详情</h3></div><button type="button" @click="selectedBlacklist = null"><X :size="18" /></button></header><div class="security-drawer-body"><div class="detail-icon"><Ban :size="20" /></div><dl class="detail-list"><div><dt>类型</dt><dd>{{ typeLabels[selectedBlacklist.type] || selectedBlacklist.type }}</dd></div><div><dt>对象</dt><dd>{{ selectedBlacklist.object }}</dd></div><div><dt>风险原因</dt><dd>{{ selectedBlacklist.reason }}</dd></div><div><dt>来源</dt><dd>{{ selectedBlacklist.source }}</dd></div><div><dt>加入时间</dt><dd>{{ selectedBlacklist.createdAt }}</dd></div><div><dt>有效期</dt><dd>{{ selectedBlacklist.duration }}</dd></div></dl></div><footer><button type="button" class="admin-ghost-button" @click="selectedBlacklist = null">关闭</button><button type="button" class="admin-danger-button" :disabled="selectedBlacklist.status === 'expired'" @click="confirmBlacklist(selectedBlacklist)">解除黑名单</button></footer></aside></div></Transition>
      <Transition name="security-drawer"><div v-if="selectedEvent" class="security-overlay" @pointerdown.self="selectedEvent = null"><aside class="security-drawer"><header><div><span>安全审计事件</span><h3>事件详情</h3></div><button type="button" @click="selectedEvent = null"><X :size="18" /></button></header><div class="security-drawer-body"><div class="event-heading"><span class="security-risk-tag" :class="`is-${selectedEvent.level}`"><i></i>{{ levels[selectedEvent.level] }}</span><strong>{{ selectedEvent.id }}</strong></div><dl class="detail-list"><div><dt>发生时间</dt><dd>{{ selectedEvent.timestamp }}</dd></div><div><dt>事件类型</dt><dd>{{ types[selectedEvent.type] || selectedEvent.type }}</dd></div><div><dt>用户ID</dt><dd>{{ selectedEvent.userId }}</dd></div><div><dt>脱敏IP</dt><dd>{{ selectedEvent.maskedIp }}</dd></div><div class="wide"><dt>风险描述</dt><dd>{{ selectedEvent.summary }}</dd></div><div class="wide"><dt>命中规则</dt><dd>{{ selectedEvent.rule }}</dd></div><div class="wide"><dt>Trace ID</dt><dd>{{ selectedEvent.traceId }}</dd></div></dl><div v-if="selectedEvent.sensitive" class="sensitive-note"><ShieldAlert :size="15" />具体敏感文本已脱敏，仅展示风险标签与摘要。</div></div><footer><button type="button" class="admin-ghost-button" @click="updateEvent(selectedEvent, 'ignored')">忽略事件</button><button type="button" class="admin-danger-button" @click="confirmBlock(selectedEvent)"><Ban :size="14" />立即封禁</button><button type="button" class="admin-primary-button" :disabled="isSaving" @click="updateEvent(selectedEvent, 'processed')"><CheckCircle2 :size="14" />标记已处理</button></footer></aside></div></Transition>
      <Transition name="security-drawer"><div v-if="showAudit" class="security-overlay" @pointerdown.self="showAudit = false"><aside class="security-drawer audit-drawer"><header><div><span>安全审计</span><h3>风险操作记录</h3></div><button type="button" @click="showAudit = false"><X :size="18" /></button></header><div class="security-drawer-body"><div v-if="auditLoading" class="loading">正在加载操作记录...</div><table v-else class="security-table"><thead><tr><th>管理员</th><th>操作类型</th><th>对象</th><th>时间</th><th>结果</th></tr></thead><tbody><tr v-for="log in audits" :key="log.id"><td>{{ log.actor || 'admin' }}</td><td>{{ log.action }}</td><td>{{ log.targetId || log.detail || '—' }}</td><td>{{ formatDate(log.createdAt) }}</td><td>{{ log.result || '成功' }}</td></tr><tr v-if="!audits.length"><td colspan="5" class="security-empty">暂无安全操作记录</td></tr></tbody></table></div></aside></div></Transition>
      <Transition name="security-confirm"><div v-if="confirmAction" class="security-overlay confirm-overlay" @pointerdown.self="confirmAction = null"><section class="confirm-card"><span><AlertTriangle :size="20" /></span><h3>{{ confirmAction.type === 'remove' ? '确定解除黑名单吗？' : '确定立即封禁风险对象吗？' }}</h3><p>{{ confirmAction.type === 'remove' ? `将解除对象 ${confirmAction.item.object} 的安全限制。` : `将对事件 ${confirmAction.event.id} 的风险对象临时封禁24小时。` }}</p><footer><button type="button" class="admin-ghost-button" @click="confirmAction = null">取消</button><button type="button" class="admin-danger-button" :disabled="isSaving" @click="executeConfirm">确认操作</button></footer></section></div></Transition>
